import React from 'react';
import { Outlet, NavLink, useLocation } from 'react-router-dom';

const TrangChuCuDan = () => {
    const location = useLocation();

    const menuItems = [
        { name: 'Quản lý thông báo', path: 'thong-bao', icon: '🔔' },
        { name: 'Thông tin cá nhân', path: 'thong-tin', icon: '👤' },
        { name: 'Xem hóa đơn', path: 'hoa-don', icon: '📄' },
        { name: 'Thanh toán (nếu có)', path: 'thanh-toan', icon: '💳' },
        { name: 'Gửi yêu cầu bảo trì', path: 'bao-tri', icon: '🔧' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien', icon: '🚗' },
        { name: 'Đăng ký bãi đỗ xe', path: 'dang-ky-xe', icon: '🅿️' },
    ];

    return (
        <div style={styles.container}>
            {/* 1. Lớp nền ảnh mờ tòa nhà bao phủ toàn bộ vùng content */}
            <div className="dashboard-background" />

            {/* Sidebar thiết kế Dark Navy hiện đại */}
            <div style={styles.sidebar}>
                <div style={styles.logo}>🏢 A&RMS</div>
                <nav style={styles.nav}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-cu-dan/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navLink,
                                backgroundColor: isActive ? 'rgba(255, 255, 255, 0.1)' : 'transparent',
                                color: isActive ? '#4caf50' : '#a0aec0',
                                borderRadius: '12px',
                                margin: '4px 15px'
                            })}
                        >
                            <span style={styles.icon}>{item.icon}</span> {item.name}
                        </NavLink>
                    ))}
                </nav>
            </div>

            <div style={styles.content}>
                <header style={styles.header}>
                    <span style={{color: '#718096', fontSize: '14px'}}>Cư dân / Bảng điều khiển</span>
                    <div style={styles.userIcon}>
                        <span style={styles.statusDot}></span> Phan Vinh - Phòng A101
                    </div>
                </header>

                <main style={styles.main}>
                    {/* 2. Hero Section: Đón chào cư dân (Chỉ hiện ở trang chủ thông báo) */}
                    {location.pathname.includes('thong-bao') && (
                        <div style={styles.hero}>
                            <div style={styles.welcomeText}>
                                <h1 style={{fontSize: '28px', margin: 0, color: '#2d3748'}}>Xin chào, Phan Vinh! 👋</h1>
                                <p style={{color: '#718096', marginTop: '5px'}}>Chào mừng bạn trở về nhà. Hôm nay tòa nhà có tin mới cho bạn.</p>
                            </div>
                            <div style={styles.quickStats}>
                                <div className="modern-card" style={styles.statBox}>
                                    <small style={{color: '#718096'}}>Phí tháng 04</small>
                                    <h3 style={{margin: '5px 0', color: '#e53e3e'}}>500.000đ</h3>
                                </div>
                                <div className="modern-card" style={styles.statBox}>
                                    <small style={{color: '#718096'}}>Thông báo mới</small>
                                    <h3 style={{margin: '5px 0', color: '#38a169'}}>02</h3>
                                </div>
                            </div>
                        </div>
                    )}

                    {/* 3. Vùng hiển thị nội dung các trang con bọc trong Thẻ trắng */}
                    <div className="modern-card" style={{minHeight: '500px'}}>
                        <Outlet /> 
                    </div>
                </main>
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', height: '100vh', position: 'relative', overflow: 'hidden' },
    sidebar: { width: '280px', backgroundColor: '#1a202c', color: '#fff', display: 'flex', flexDirection: 'column', zIndex: 10 },
    logo: { padding: '30px 20px', fontSize: '24px', fontWeight: '800', textAlign: 'center', color: '#fff' },
    nav: { display: 'flex', flexDirection: 'column', marginTop: '10px' },
    navLink: { padding: '12px 15px', textDecoration: 'none', fontSize: '14px', display: 'flex', alignItems: 'center', transition: '0.2s' },
    icon: { marginRight: '12px', fontSize: '18px' },
    content: { flex: 1, display: 'flex', flexDirection: 'column', zIndex: 5 },
    header: { 
        height: '70px', 
        backgroundColor: 'rgba(255, 255, 255, 0.8)', 
        backdropFilter: 'blur(10px)', 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'space-between', 
        padding: '0 30px',
        borderBottom: '1px solid rgba(0,0,0,0.05)'
    },
    main: { padding: '30px', flex: 1, overflowY: 'auto' },
    hero: { display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '30px' },
    quickStats: { display: 'flex', gap: '15px' },
    statBox: { padding: '15px 25px', textAlign: 'center', minWidth: '150px' },
    userIcon: { backgroundColor: '#fff', padding: '8px 16px', borderRadius: '30px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)', fontSize: '14px', fontWeight: '600', display: 'flex', alignItems: 'center', gap: '8px' },
    statusDot: { width: '8px', height: '8px', backgroundColor: '#48bb78', borderRadius: '50%' }
};

export default TrangChuCuDan;
